"""Utilities for writing dataset records generated by the Streamlit tool.

This module defines a :class:`DatasetRecord` dataclass representing a single
exercise session and a :func:`write_record` helper that appends the record to a
JSON Lines file.  The default output file can be configured through the
``DATASET_FILE`` environment variable.  The format follows the specification in
README.md.
"""

from __future__ import annotations

from dataclasses import dataclass, asdict
from datetime import datetime
from typing import Dict, List, Any
import json
import os

# Default path where dataset records are stored.  Can be overridden via env var
DEFAULT_DATASET_FILE = os.getenv("DATASET_FILE", "datasets/generated.jsonl")


@dataclass
class DatasetRecord:
    """Structured representation of a single dataset entry.

    Attributes
    ----------
    image_path:
        Path to the uploaded exercise image.
    prompt_final:
        Final descriptive prompt provided to the code generator.
    code_final:
        Final Manim code used to render the video.
    video_path:
        Path or URL to the rendered video file.
    rules_applied:
        List of persistent rules applied during generation.
    chat_history:
        Sequence of chat messages. Each message is a mapping with ``role`` and
        ``content`` keys.
    model_metadata:
        Information about the models used (name, version, etc.).
    timestamp:
        ISO formatted UTC timestamp when the record was saved.
    user_id:
        Identifier of the user who created the record.
    """

    image_path: str
    prompt_final: str
    code_final: str
    video_path: str
    rules_applied: List[str]
    chat_history: List[Dict[str, str]]
    model_metadata: Dict[str, str]
    timestamp: str
    user_id: str


def write_record(record: DatasetRecord, file_path: str = DEFAULT_DATASET_FILE) -> None:
    """Append ``record`` to the dataset file as a JSON object.

    Parameters
    ----------
    record:
        The :class:`DatasetRecord` instance to persist.
    file_path:
        Location of the JSONL file.  The parent directory is created if it does
        not yet exist.
    """

    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, "a", encoding="utf-8") as f:
        json.dump(asdict(record), f, ensure_ascii=False)
        f.write("\n")
